import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const y=JSON.parse(`{"title":"accessibility Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"accessibility","tag":"accessibility","title":"accessibility Tag","prev":null,"next":null,"posts":[{"title":"提高网页的易读性","url":"/posts/2021-02-06-web-accessibility/","date":"2021-02-06 11:04","tags":["accessibility"],"html":"<p>正常人可以通过鼠标和键盘来操作浏览器，使用滚轮来滚动网页，使用鼠标左键和右键来执行操作，使用键盘输入内容。但是对于残疾人来说可能就不是这样的了，如果一个人身体行动不便只能通过键盘敲击来操作电脑，无法使用鼠标的情况下，如果网页不支持键盘 <code>Tab</code> 键来切换各种点击按钮，那就会给残疾人的使用带来困难。如果视力不好的人只能借助屏幕阅读器来查看网页，如果按钮或者图片没有合适的标签信息，那就无法通过屏幕阅读器来听到这个按钮或者图片的含义。我们不仅要考虑正常人如何查看网页，也需要顾及到特殊人群的需求，这样才能让每个人都享受到互联网带来的便利。</p>\\n<h2 id=\\"focus\\" tabindex=\\"-1\\">focus <a class=\\"header-anchor\\" href=\\"#focus\\" aria-label=\\"Permalink to &quot;focus&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>focus 状态对于网页易读性非常重要，foucs 决定了键盘事件的去向。但是我们在项目开发的时候经常会给 <code>button</code> 添加鼠标的 <code>hover</code> 状态，却忘记了添加 <code>focus</code> 状态。添加 <code>hover</code> 状态的 CSS 时，记得同时添加 <code>focus</code> 状态的 CSS。同时，浏览器会有默认的 <code>focus</code> 样式， Chrome 下是使用 <code>outline</code> 属性添加高亮的蓝色边框，记得不要轻易覆盖这个属性为 <code>none</code>。\\n但是并不是所有的 HTML 元素都是可以 <code>focus</code> 的，下面是查找可以 <code>focus</code> 的元素的方法。</p>\\n<div class=\\"language-ts line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ts</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> candidateSelectors</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> [</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  'input:not([disabled])'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  'select:not([disabled])'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  'textarea:not([disabled])'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  'a[href]'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  'area[href]'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  'button:not([disabled])'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  '[tabindex=\\"0\\"]'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  'audio[controls]'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  'video[controls]'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  '[contenteditable]:not([contenteditable=\\"false\\"])'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  'details>summary'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> candidateSelector</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> candidateSelectors.</span><span style=\\"color:#6F42C1\\">join</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">','</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">type</span><span style=\\"color:#6F42C1\\"> Option</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  shouldIgnoreVisibility</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> boolean</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> defaultOption</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Option</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  shouldIgnoreVisibility: </span><span style=\\"color:#005CC5\\">false</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> isDisplayNone</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">node</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Element</span><span style=\\"color:#D73A49\\"> |</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> boolean</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">!</span><span style=\\"color:#24292E\\">node) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#6F42C1\\">getComputedStyle</span><span style=\\"color:#24292E\\">(node).display </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> 'none'</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">return</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#6F42C1\\"> isDisplayNone</span><span style=\\"color:#24292E\\">(node.parentElement);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> isHidden</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">node</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Element</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#6F42C1\\">getComputedStyle</span><span style=\\"color:#24292E\\">(node).visibility </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> 'hidden'</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">return</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#6F42C1\\">isDisplayNone</span><span style=\\"color:#24292E\\">(node)) </span><span style=\\"color:#D73A49\\">return</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> function</span><span style=\\"color:#6F42C1\\"> tabbable</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">el</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> HTMLElement</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">option</span><span style=\\"color:#D73A49\\">?:</span><span style=\\"color:#6F42C1\\"> Partial</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">Option</span><span style=\\"color:#24292E\\">>) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> mergedOption</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    ...</span><span style=\\"color:#24292E\\">defaultOption,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    ...</span><span style=\\"color:#24292E\\">option</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> candidates</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> Array.</span><span style=\\"color:#6F42C1\\">from</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    el.</span><span style=\\"color:#6F42C1\\">querySelectorAll</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">HTMLElement</span><span style=\\"color:#24292E\\">>(candidateSelector)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (mergedOption.shouldIgnoreVisibility) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> candidates;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> candidates.</span><span style=\\"color:#6F42C1\\">filter</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">candidate</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#D73A49\\"> !</span><span style=\\"color:#6F42C1\\">isHidden</span><span style=\\"color:#24292E\\">(candidate));</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br><span class=\\"line-number\\">42</span><br><span class=\\"line-number\\">43</span><br><span class=\\"line-number\\">44</span><br><span class=\\"line-number\\">45</span><br><span class=\\"line-number\\">46</span><br><span class=\\"line-number\\">47</span><br><span class=\\"line-number\\">48</span><br><span class=\\"line-number\\">49</span><br><span class=\\"line-number\\">50</span><br></div></div><h2 id=\\"dom-order\\" tabindex=\\"-1\\">DOM Order <a class=\\"header-anchor\\" href=\\"#dom-order\\" aria-label=\\"Permalink to &quot;DOM Order&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>当你使用键盘的 <code>Tab</code> 来选择下一个按钮的时候，是如何决定顺序的呢？ 答案是根据 DOM 的顺序而不是界面上 UI 的顺序，你可以使用 CSS 来调整 UI 顺序，但是 <code>Tab</code> 顺序不会改变。\\n针对隐藏的元素， <code>Tab</code> 键也不会触发这个元素的 <code>focus</code>，隐藏的元素 CSS 属性可能含有 <code>display: none</code> 或者 <code>visibility: hidden</code>。</p>\\n<h2 id=\\"tabindex\\" tabindex=\\"-1\\">tabindex <a class=\\"header-anchor\\" href=\\"#tabindex\\" aria-label=\\"Permalink to &quot;tabindex&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>对于 <code>button</code> 和 <code>a</code> 元素，当然是可以 <code>focus</code> 的，但是针对类似 <code>div</code> 这样的元素，如何让它可以 <code>focus</code> 呢？ 答案是添加 <code>tabindex</code> 属性。</p>\\n<div class=\\"language-html line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">html</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">custom-button</span><span style=\\"color:#6F42C1\\"> tabindex</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"0\\"</span><span style=\\"color:#24292E\\">>Press Tab to Focus Me!&#x3C;/</span><span style=\\"color:#22863A\\">custom-button</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>通过添加 <code>tabindex=&quot;0&quot;</code> 可以使这个元素被 <code>focus</code>。那么如何使一个元素不被 <code>focus</code>呢？</p>\\n<div class=\\"language-html line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">html</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">button</span><span style=\\"color:#6F42C1\\"> id</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"foo\\"</span><span style=\\"color:#6F42C1\\"> tabindex</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"-1\\"</span><span style=\\"color:#24292E\\">>I'm not keyboard focusable&#x3C;/</span><span style=\\"color:#22863A\\">button</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">button</span><span style=\\"color:#6F42C1\\"> onclick</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"</span><span style=\\"color:#24292E\\">foo</span><span style=\\"color:#032F62\\">.</span><span style=\\"color:#6F42C1\\">focus</span><span style=\\"color:#032F62\\">();\\"</span><span style=\\"color:#24292E\\">>Focus my sibling&#x3C;/</span><span style=\\"color:#22863A\\">button</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>使用 <code>tabindex=&quot;-1&quot;</code> 可以确保这个元素不会使用键盘 <code>focus</code>，但是鼠标没有影响。\\n<code>tabindex</code> 当然可以设置大于 0 的值，但我们不推荐这么做，因为默认元素的 <code>tabindex</code> 都是 0，所以大于 0 的元素最后才会触发 <code>focus</code>。\\n现在的网页开发，我们都会自己手动实现 <code>select</code> 或者 <code>dropdown</code> 元素，但由于这些不是默认的 HTML 元素，所以需要自己实现键盘的 <code>Tab</code> 键或者方向键的触发。</p>\\n<h2 id=\\"modals-and-keyboard-traps\\" tabindex=\\"-1\\">Modals and keyboard traps <a class=\\"header-anchor\\" href=\\"#modals-and-keyboard-traps\\" aria-label=\\"Permalink to &quot;Modals and keyboard traps&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>网页开发中经常会出现弹窗，在有弹窗的情况下我们是不能选中背景中的元素的，所以我们需要手动处理 <code>Tab</code> 键保证只有 <code>Modal</code> 里的元素可以被 <code>focus</code>。并且在关闭 <code>Modal</code> 的时候 <code>focus</code> 回原来的元素。</p>\\n<h2 id=\\"semantics-and-aria\\" tabindex=\\"-1\\">Semantics and ARIA <a class=\\"header-anchor\\" href=\\"#semantics-and-aria\\" aria-label=\\"Permalink to &quot;Semantics and ARIA&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我们经常使用 HTML 元素来模拟一些功能，例如使用 <code>button</code> 按钮来模拟菜单功能。这时候我们需要为 <code>button</code> 添加 <code>aria-label</code> 属性方便屏幕阅读器理解这个按钮代表的含义。</p>\\n<div class=\\"language-html line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">html</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">button</span><span style=\\"color:#6F42C1\\"> aria-label</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"menu\\"</span><span style=\\"color:#24292E\\">>&#x3C;/</span><span style=\\"color:#22863A\\">button</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>当然啦，这种类似的属性还有很多，例如 <code>role</code> 属性来描述这个元素的定位。</p>\\n<h2 id=\\"accessibility-review\\" tabindex=\\"-1\\">Accessibility Review <a class=\\"header-anchor\\" href=\\"#accessibility-review\\" aria-label=\\"Permalink to &quot;Accessibility Review&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>如何检查自己网页的易读性呢，现在也有现成的网页工具和可以集成的 CI 工具。我们可以使用 Chrome 浏览器自带的 <code>Lighthouse</code> 来检查自己网页的易读性。如果想集成 CI 的话，可以试试<a href=\\"https://github.com/dequelabs/axe-core\\" target=\\"_blank\\" rel=\\"noreferrer\\">axe-core</a></p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>提高网页的易读性，不仅可以使用键盘提高操作网页的便利性，也可以照顾特殊人群的使用，何乐而不为呢。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://github.com/udacity/ud891/tree/gh-pages/lesson2-focus/07-modals-and-keyboard-traps/solution\\" target=\\"_blank\\" rel=\\"noreferrer\\">Modals and keyboard traps sample code</a></p>\\n<p><a href=\\"https://developers.google.com/web/fundamentals/accessibility\\" target=\\"_blank\\" rel=\\"noreferrer\\">Accessibility</a></p>\\n<p><a href=\\"https://www.w3.org/TR/wai-aria-practices-1.1/\\" target=\\"_blank\\" rel=\\"noreferrer\\">WAI-ARIA Authoring Practices</a></p>\\n"}]},"relativePath":"tags/accessibility/index.md","filePath":"tags/[slug].md"}`),e={name:"tags/accessibility/index.md"};function l(o,p,c,r,t,i){return n(),a("div")}const b=s(e,[["render",l]]);export{y as __pageData,b as default};
